    @inline(__always)
    private func checkHalfVectorResizingFromDoubleConstantA(_ value: Lane) {
        let mismatches = Mismatches("halfVectorResizingFromDouble with a repeating \(hex(value))")
        mismatches.check(
            H.repeating(value),
            H(raw: HighwayReference.repeatingF64(value)),
            "repeating"
        )
        let port = H.halfVector(resizing: H.repeating(value))
        let reference = H.HalfVector(
            raw: HighwayReference.halfVectorResizingF64ToF64(H.repeating(value).raw)
        )
        let definedBytes = SIMD<Double>.laneCount * MemoryLayout<Double>.stride
        let grownBytes = H.HalfVector.laneCount * MemoryLayout<Lane>.stride
        let newBytes = HighwayReference.resizedBytesDefined(definedBytes, grownBytes, definedBytes)
        mismatches.check(
            Array(bytes(of: port).prefix(definedBytes)),
            Array(bytes(of: reference).prefix(definedBytes)),
            ""
        )
        mismatches.check(
            Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
            Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
            ""
        )
        mismatches.record()
    }

